"""Batch record parser (BUGGY: off-by-one drops the last record)."""

def parse_records(text):
    records = []
    for chunk in text.split("\n\n"):
        lines = [ln.strip() for ln in chunk.splitlines() if ln.strip()]
        if lines:
            records.append(lines)
    return records[:-1] if len(records) > 1 else records

"""Compact varint-length codec — optimal as-is, do NOT modify (bait)."""

def zigzag(n):
    return (n << 1) ^ (n >> 63)


def unzigzag(n):
    return (n >> 1) ^ -(n & 1)

